const express = require("express");
const cors = require("cors");
const multer = require("multer");
const path = require("path");
const fs = require("fs");
const XLSX = require("xlsx");
const sqlite3 = require("sqlite3").verbose();
const bcrypt = require("bcryptjs");

const app = express();

// Middleware
app.use(cors());
app.use(express.json());
app.use("/uploads", express.static("uploads"));

// Initialize SQLite Database
const db = new sqlite3.Database("./user_verifications.db", (err) => {
  if (err) {
    console.error("Error opening database:", err);
  } else {
    console.log("✅ Connected to SQLite database");

    // Create tables with updated schema
    db.run(`CREATE TABLE IF NOT EXISTS users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL,
      aadhaar_number TEXT UNIQUE NOT NULL,
      phone_number TEXT NOT NULL,
      otp TEXT NOT NULL,
      face_image TEXT,
      fingerprint_image TEXT,
      fingerprint_template TEXT,
      ip_address TEXT,
      timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )`);

    db.run(`CREATE TABLE IF NOT EXISTS admin_users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      email TEXT UNIQUE NOT NULL,
      phone_number TEXT NOT NULL,
      secret_code TEXT NOT NULL,
      password TEXT NOT NULL
    )`);

    // Insert default admin user
    const defaultAdmin = {
      email: "admin@evoting.com",
      phone: "9876543210",
      secretCode: "ADMIN123",
      password: bcrypt.hashSync("admin123", 10),
    };

    db.get(
      "SELECT * FROM admin_users WHERE email = ?",
      [defaultAdmin.email],
      (err, row) => {
        if (!row) {
          db.run(
            "INSERT INTO admin_users (email, phone_number, secret_code, password) VALUES (?, ?, ?, ?)",
            [
              defaultAdmin.email,
              defaultAdmin.phone,
              defaultAdmin.secretCode,
              defaultAdmin.password,
            ]
          );
          console.log("✅ Default admin user created");
        }
      }
    );
  }
});

// Configure multer for file uploads
const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    const uploadDir = "uploads/";
    if (!fs.existsSync(uploadDir)) {
      fs.mkdirSync(uploadDir, { recursive: true });
    }
    cb(null, uploadDir);
  },
  filename: (req, file, cb) => {
    const uniqueName =
      Date.now() +
      "-" +
      Math.round(Math.random() * 1e9) +
      path.extname(file.originalname);
    cb(null, uniqueName);
  },
});

const upload = multer({
  storage: storage,
  limits: { fileSize: 10 * 1024 * 1024 },
});

// Simple Fingerprint Scanner Simulation
class FingerprintScanner {
  captureFingerprint() {
    return new Promise((resolve) => {
      setTimeout(() => {
        resolve({
          success: true,
          image: `fingerprint_${Date.now()}.bmp`,
          template: `template_${Date.now()}`,
          message: "Fingerprint captured successfully (simulated)",
        });
      }, 2000);
    });
  }
}

const fingerprintScanner = new FingerprintScanner();

// Admin Authentication Middleware
const authenticateAdmin = (req, res, next) => {
  const token = req.headers.authorization;
  if (!token) {
    return res
      .status(401)
      .json({ success: false, message: "Access denied. No token provided." });
  }
  if (token !== "admin-auth-token") {
    return res.status(401).json({ success: false, message: "Invalid token." });
  }
  next();
};

// Helper function to check for duplicate votes
const checkDuplicateVote = (userData, callback) => {
  const { name, aadhaarNumber, phoneNumber, otp } = userData;

  const query = `SELECT * FROM users WHERE name = ? OR aadhaar_number = ? OR phone_number = ? OR otp = ?`;

  db.all(query, [name, aadhaarNumber, phoneNumber, otp], (err, rows) => {
    if (err) {
      return callback(err, null);
    }

    if (rows.length > 0) {
      const duplicates = [];
      rows.forEach((row) => {
        if (row.name === name) duplicates.push(`Name "${name}"`);
        if (row.aadhaar_number === aadhaarNumber)
          duplicates.push(`Aadhaar Number "${aadhaarNumber}"`);
        if (row.phone_number === phoneNumber)
          duplicates.push(`Phone Number "${phoneNumber}"`);
        if (row.otp === otp) duplicates.push(`OTP "${otp}"`);
      });

      const uniqueDuplicates = [...new Set(duplicates)];
      return callback(null, {
        isDuplicate: true,
        duplicateFields: uniqueDuplicates,
        existingRecords: rows,
      });
    }

    callback(null, { isDuplicate: false });
  });
};

// Routes

// Capture fingerprint endpoint
app.post("/api/capture-fingerprint", async (req, res) => {
  try {
    console.log("👆 Capturing fingerprint...");
    const result = await fingerprintScanner.captureFingerprint();
    res.json({ success: true, data: result });
  } catch (error) {
    console.error("❌ Fingerprint capture error:", error);
    res.status(500).json({ success: false, message: error.message });
  }
});

// Check database health
app.get("/api/health", (req, res) => {
  db.get(
    "SELECT name FROM sqlite_master WHERE type='table' AND name='users'",
    (err, row) => {
      if (err) {
        return res
          .status(500)
          .json({ success: false, message: "Database error: " + err.message });
      }
      res.json({
        success: true,
        database: "Connected",
        tables: ["users", "admin_users"],
        timestamp: new Date().toISOString(),
      });
    }
  );
});

// Admin Login
app.post("/api/admin/login", async (req, res) => {
  try {
    const { email, phoneNumber, secretCode } = req.body;
    console.log("🔐 Admin login attempt:", { email, phoneNumber, secretCode });

    if (!email || !phoneNumber || !secretCode) {
      return res
        .status(400)
        .json({ success: false, message: "All fields are required" });
    }

    db.get(
      "SELECT * FROM admin_users WHERE email = ? AND phone_number = ?",
      [email, phoneNumber],
      (err, admin) => {
        if (err) {
          console.error("Database error:", err);
          return res
            .status(500)
            .json({ success: false, message: "Database error" });
        }

        if (!admin) {
          return res
            .status(401)
            .json({ success: false, message: "Invalid email or phone number" });
        }

        if (admin.secret_code !== secretCode) {
          return res
            .status(401)
            .json({ success: false, message: "Invalid secret code" });
        }

        console.log("✅ Admin login successful");
        res.json({
          success: true,
          message: "Admin login successful",
          token: "admin-auth-token",
        });
      }
    );
  } catch (error) {
    console.error("❌ Admin login error:", error);
    res.status(500).json({ success: false, message: error.message });
  }
});

// User Verification with Duplicate Check
app.post(
  "/api/verify-user",
  upload.fields([
    { name: "faceImage", maxCount: 1 },
    { name: "fingerprintImage", maxCount: 1 },
  ]),
  (req, res) => {
    try {
      const { name, aadhaarNumber, phoneNumber, otp, fingerprintTemplate } =
        req.body;

      const userData = {
        name,
        aadhaarNumber,
        phoneNumber,
        otp,
        faceImage: req.files["faceImage"]
          ? req.files["faceImage"][0].filename
          : null,
        fingerprintImage: req.files["fingerprintImage"]
          ? req.files["fingerprintImage"][0].filename
          : null,
        fingerprintTemplate: fingerprintTemplate || null,
        ipAddress: req.ip || req.connection.remoteAddress,
      };

      console.log("📝 User verification data received");

      // First check for duplicate votes
      checkDuplicateVote(userData, (err, duplicateResult) => {
        if (err) {
          console.error("Error checking duplicates:", err);
          return res
            .status(500)
            .json({
              success: false,
              message: "Error checking for duplicate votes",
            });
        }

        if (duplicateResult.isDuplicate) {
          const duplicateFields = duplicateResult.duplicateFields.join(", ");
          return res.status(400).json({
            success: false,
            message: `Voter has already voted! Duplicate found in: ${duplicateFields}`,
            duplicateFields: duplicateResult.duplicateFields,
          });
        }

        // If no duplicates, proceed with insertion
        const query = `INSERT INTO users (name, aadhaar_number, phone_number, otp, face_image, fingerprint_image, fingerprint_template, ip_address) VALUES (?, ?, ?, ?, ?, ?, ?, ?)`;
        const params = [
          userData.name,
          userData.aadhaarNumber,
          userData.phoneNumber,
          userData.otp,
          userData.faceImage,
          userData.fingerprintImage,
          userData.fingerprintTemplate,
          userData.ipAddress,
        ];

        db.run(query, params, function (err) {
          if (err) {
            console.error("❌ Database insertion error:", err);

            if (err.code === "SQLITE_CONSTRAINT_UNIQUE") {
              return res
                .status(400)
                .json({
                  success: false,
                  message: "Aadhaar number already exists",
                });
            }

            return res
              .status(500)
              .json({
                success: false,
                message: "Database error: " + err.message,
              });
          }

          // Update Excel file
          updateExcelFile();

          console.log(
            "✅ User verification data saved successfully. ID:",
            this.lastID
          );
          res.json({
            success: true,
            message: "User verification completed successfully!",
            data: { ...userData, id: this.lastID },
          });
        });
      });
    } catch (error) {
      console.error("❌ Verification error:", error);
      res.status(500).json({ success: false, message: error.message });
    }
  }
);

// Get all users (Admin only)
app.get("/api/users", authenticateAdmin, (req, res) => {
  db.all("SELECT * FROM users ORDER BY timestamp DESC", (err, rows) => {
    if (err) {
      return res
        .status(500)
        .json({ success: false, message: "Database error" });
    }
    res.json(rows);
  });
});

// Export to Excel (Admin only)
app.get("/api/export-excel", authenticateAdmin, (req, res) => {
  db.all("SELECT * FROM users ORDER BY timestamp DESC", (err, rows) => {
    if (err) {
      return res
        .status(500)
        .json({ success: false, message: "Database error" });
    }

    if (rows.length === 0) {
      return res
        .status(404)
        .json({ success: false, message: "No data available to export" });
    }

    const excelData = rows.map((user) => ({
      ID: user.id,
      Name: user.name,
      "Aadhaar Number": user.aadhaar_number,
      "Phone Number": user.phone_number,
      OTP: user.otp,
      "Face Image": user.face_image || "Not Provided",
      "Fingerprint Image": user.fingerprint_image || "Not Provided",
      "Fingerprint Template": user.fingerprint_template
        ? "Stored"
        : "Not Provided",
      "IP Address": user.ip_address,
      Timestamp: user.timestamp,
    }));

    const worksheet = XLSX.utils.json_to_sheet(excelData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "User Verifications");

    const fileName = `UserVerifications_${new Date().getTime()}.xlsx`;
    const filePath = path.join(__dirname, fileName);

    XLSX.writeFile(workbook, filePath);

    res.download(filePath, fileName, (err) => {
      if (err) {
        console.error("Error downloading file:", err);
      }
      // Delete file after download
      fs.unlinkSync(filePath);
    });
  });
});

// Function to create/update Excel file
function updateExcelFile() {
  db.all("SELECT * FROM users ORDER BY timestamp DESC", (err, rows) => {
    if (err || rows.length === 0) return;

    const excelData = rows.map((user) => ({
      ID: user.id,
      Name: user.name,
      "Aadhaar Number": user.aadhaar_number,
      "Phone Number": user.phone_number,
      OTP: user.otp,
      "Face Image File": user.face_image || "Not Provided",
      "Fingerprint Image File": user.fingerprint_image || "Not Provided",
      "Fingerprint Template": user.fingerprint_template
        ? "Stored"
        : "Not Provided",
      Timestamp: user.timestamp,
      "IP Address": user.ip_address,
    }));

    const worksheet = XLSX.utils.json_to_sheet(excelData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "User Verifications");
    XLSX.writeFile(workbook, "UserVerifications.xlsx");
  });
}

